[{"role":"system","content":"You are grading output according to a user-specified rubric. If the statement in the rubric is true, then the output passes the test. You respond with a JSON object with this structure: {reason: string, pass: boolean, score: number}

Examples:

<Output>Hello world</Output>
<Rubric>Content contains a greeting</Rubric>
{"reason": "the content contains the word 'Hello'", "pass": true, "score": 1.0}

<Output>Avast ye swabs, repel the invaders!</Output>
<Rubric>Does not speak like a pirate</Rubric>
{"reason": "'avast ye' is a common pirate term", "pass": false, "score": 0.0}"},{"role":"user","content":"<Output>
{"world_id":"wld_aetheria","title":"Three Against the Drift","logline":"As the skybridges fray and the Toll War tightens the Drift Cartel's grip, a stubborn cartographer, a wary smuggler and a ruthless toll-master must each face their own failure and cooperate to chart a safe route before the archipelago is stranded.","theme":"Shared truths hold what hoarded power cannot","acts":[{"id":"act_setup","title":"Fraying Bridges","purpose":"setup","scenes":[{"id":"scn_silverspine_charts","title":"The Charts That Shouldn't Exist","summary":"At Silverspine Academy, Veya uses her wind-sight to finish a chart revealing that the safe skybridge routes are collapsing faster than the Wardens admit. She keeps the findings to herself, convinced she alone can prove her late mentor's theory.","location_id":"loc_silverspine","character_ids":["chr_veya"],"goal":"Complete a chart of a safe route through the breaking skybridge network.","conflict":"The chart shows the isles drifting apart, but Veya refuses to share it until it is flawless and cannot admit her earlier readings were wrong.","outcome":"She completes a partial route chart but hides it, leaving a gap in her data that she will not acknowledge."},{"id":"scn_docks_toll_hike","title":"The Price of Passage","summary":"At Mistral Docks, Kael announces a steep new skybridge toll, citing wind-debt, and quietly marks the last stable routes for Cartel control. Word reaches him that a Silverspine cartographer is mapping those very routes.","location_id":"loc_mistral_docks","character_ids":["chr_kael"],"goal":"Secure the Cartel's claim on the last stable skybridge routes.","conflict":"The Bridge Wardens accuse him of sabotaging forge-island supplies, and merchants threaten to defy the toll.","outcome":"Kael enforces the toll and resolves to obtain the cartographer's charts, recognising Veya's name.","depends_on":["scn_silverspine_charts"]},{"id":"scn_hollow_levy","title":"Grain Under Watch","summary":"In The Hollow, Maris learns Cartel enforcers will seize grain shipments under the levy. She begins moving grain through unmapped service corridors between windmills and granaries.","location_id":"loc_the_hollow","character_ids":["chr_maris"],"goal":"Smuggle enough grain to keep The Hollow fed through the crisis.","conflict":"Enforcers are closing in on her routes, and she trusts almost no one with her secrets.","outcome":"She hides the first shipment but realises she needs a safe way off the isle that avoids Cartel-watched bridges.","depends_on":["scn_docks_toll_hike"]},{"id":"scn_veya_maris_meet","title":"A Trade of Paths","summary":"Veya travels to The Hollow seeking grain-route knowledge and meets Maris. They agree to trade wind-current knowledge for secret service paths, a wary alliance.","location_id":"loc_the_hollow","character_ids":["chr_veya","chr_maris"],"goal":"Exchange Veya's wind-current knowledge for Maris's secret paths.","conflict":"Maris trusts slowly and suspects Veya's charts will end up in Cartel hands; Veya withholds her chart's gap.","outcome":"They form a cautious pact and plan to test a route together, though Veya conceals her uncertain data.","depends_on":["scn_silverspine_charts","scn_hollow_levy"]}]},{"id":"act_rising","title":"Cables Under Strain","purpose":"rising_action","scenes":[{"id":"scn_emberroost_cables","title":"Sabotage at the Forge","summary":"Veya and Maris travel to Emberroost to see whether new cloudstone cable can reinforce the route. They find supplies spoiled, and the Wardens blame Kael, but the damage hints at a more complicated truth.","location_id":"loc_emberroost","character_ids":["chr_veya","chr_maris"],"goal":"Obtain braided cloudstone cable to reinforce the charted route.","conflict":"Forge supplies have been sabotaged, and the Wardens distrust Maris's Cartel-adjacent smuggling and Veya's secrecy; no open flame may be used outside the shielded pits.","outcome":"They get a limited length of cable and a Warden's warning that the Cartel is hunting Veya's charts.","depends_on":["scn_veya_maris_meet"]},{"id":"scn_docks_ambush","title":"Kael's Offer","summary":"At Mistral Docks, Kael intercepts Veya and Maris and offers a charming bargain: hand over the charts and the Hollow's levy will be eased. Veya refuses to let him control them, and Maris is tempted.","location_id":"loc_mistral_docks","character_ids":["chr_veya","chr_kael","chr_maris"],"goal":"Kael seeks to obtain the charts; Veya seeks to pass the docks without surrendering them.","conflict":"Kael's ledger-mastery exposes Maris's smuggling as leverage while Veya's pride makes her reject any compromise.","outcome":"They escape with the charts, but Maris learns Veya hid the flaw in her data, straining their pact.","depends_on":["scn_emberroost_cables"]},{"id":"scn_silverspine_error","title":"The Mistake in the Margin","summary":"Back at Silverspine, a Warden cartographer shows that Veya's key reading was wrong and the planned route would fail. Veya, unable to admit error, argues until Maris leaves in anger.","location_id":"loc_silverspine","character_ids":["chr_veya","chr_maris"],"goal":"Veya wants to validate her route; Maris wants the truth about its safety.","conflict":"Veya's inability to admit being wrong clashes with Maris's slow trust and rarely forgiving nature.","outcome":"Maris departs for The Hollow and Veya is left alone with a failing chart and the Cartel closing in.","depends_on":["scn_docks_ambush"]},{"id":"scn_hollow_raid","title":"The Silos Burn Dry","summary":"Enforcers seize Hollow granaries using Maris's routes, which Kael deduced from her leaked trade. Maris must choose between loyalty to home and her friendship with Veya.","location_id":"loc_the_hollow","character_ids":["chr_maris","chr_kael"],"goal":"Maris wants to protect the remaining grain; Kael wants to break the Hollow's resistance to secure the levy.","conflict":"Kael's pragmatism meets Maris's resourcefulness, but she is cornered and the Hollow Circle begs her to surrender the routes.","outcome":"Maris saves a portion of the grain but recognises that hiding alone cannot save the isle, and she needs Veya's wind-sight.","depends_on":["scn_silverspine_error"]},{"id":"scn_veya_admits","title":"Admitting the Drift","summary":"Veya follows Maris to The Hollow, admits her error, and offers to share the full chart with the Hollow Circle and the Wardens. Her honesty rebuilds fragile trust.","location_id":"loc_the_hollow","character_ids":["chr_veya","chr_maris"],"goal":"Veya wants to repair the pact and correct the route; Maris wants the truth before risking her people.","conflict":"Veya's pride resists confession, and Maris's grudge makes forgiveness costly.","outcome":"They agree to rebuild the route together, using Veya's wind-sight and Maris's corridors, and to confront Kael at the last stable bridge.","depends_on":["scn_hollow_raid"]}]},{"id":"act_climax","title":"The Last Stable Bridge","purpose":"climax","scenes":[{"id":"scn_climax_crossing","title":"Crossing the Breaking Span","summary":"Veya, Maris and Kael meet at the last stable skybridge near Emberroost as strain on the cables mounts. Kael arrives to seize the route and finds Veya's corrected chart shows the span will fail under Cartel tolls and heavy trade.","location_id":"loc_emberroost","character_ids":["chr_veya","chr_maris","chr_kael"],"goal":"Veya and Maris want to reinforce the span and chart a safe crossing; Kael wants to seize the route for the Cartel.","conflict":"Kael's monopoly aim collides with the bridge's imminent failure while Veya's wind-sight and Maris's corridors are the only way across.","outcome":"The span begins to fail and Kael must decide whether to hold control or help.","depends_on":["scn_veya_admits","scn_emberroost_cables"]},{"id":"scn_climax_cooperation","title":"Three Hands on the Cable","summary":"Kael uses ledger-mastery to find the weak point in the span's load while Veya reads the wind and Maris leads the crews through service corridors to brace the cable. Working together they stabilise the bridge, and Kael realises control cost him more than it gained.","location_id":"loc_emberroost","character_ids":["chr_veya","chr_maris","chr_kael"],"goal":"Stabilise the failing span before it severs.","conflict":"Each must rely on a person they distrust, and Kael's price-equals-worth habit tempts him to bargain at the worst moment.","outcome":"The bridge holds, and Kael relinquishes his claim on the route.","depends_on":["scn_climax_crossing"]}]},{"id":"act_resolution","title":"Shared Routes","purpose":"resolution","scenes":[{"id":"scn_res_silverspine_share","title":"Charts for All","summary":"Veya presents the corrected charts at Silverspine Academy and shares them openly with the Wardens and the Hollow Circle. She credits Maris and acknowledges her mentor's theory was only partly right.","location_id":"loc_silverspine","character_ids":["chr_veya","chr_maris"],"goal":"Share the charts openly so all isles can use safe routes.","conflict":"Some scholars resist because the charts contradict their records, and Veya must admit her earlier error publicly.","outcome":"The charts are adopted network-wide and the Wardens begin reinforcing routes.","depends_on":["scn_climax_cooperation"]},{"id":"scn_res_docks_toll","title":"A Fairer Ledger","summary":"At Mistral Docks, Kael faces the Cartel and cuts the skybridge toll and lifts the grain levy in exchange for labour on bridge repairs under the wind-debt rule. Cartel princes grumble but are bound by the stability he proved.","location_id":"loc_mistral_docks","character_ids":["chr_kael"],"goal":"End the toll war on terms that keep the bridges standing.","conflict":"Cartel princes resist losing profit and Kael's old habit of valuing everything by price resurfaces.","outcome":"The toll is lowered and the levy lifted, easing the Toll War and the Grain Levy.","depends_on":["scn_climax_cooperation"]},{"id":"scn_res_hollow_harvest","title":"Windmills Turning","summary":"In The Hollow, grain flows freely again. Maris, Veya and a wary Kael meet at the windmills, where Maris accepts that hiding can be as brave as standing still and offers cautious forgiveness.","location_id":"loc_the_hollow","character_ids":["chr_maris","chr_veya","chr_kael"],"goal":"Restore the Hollow's grain trade and mend the three rivals' broken trust.","conflict":"Maris rarely forgives and Kael must repay the wind-debt for his sabotage while Veya's pride briefly flares.","outcome":"A fragile peace settles over the archipelago as the three agree to keep sharing routes and repairs.","depends_on":["scn_res_silverspine_share","scn_res_docks_toll"]}]}]}
